// VU_FLOAT constructor: moves a float into a VU quadword's x (an out-of-line inline copy in the linkonce area).
inline VU_FLOAT::VU_FLOAT(float f) { __asm__("mfc1 %0, %1" : "=r"(q) : "f"(f)); }

